$_MODULE['<{amazonmarketplacepro}prestashop>configure_af6dd5c53d00465bccc957cc7b971ba0'] = 'Käuferdaten löschen nach';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_07e932ebe6b3a0cfb938682b7f857e92'] = 'Amazons Datenschutzrichtlinie verlangt, Käuferdaten innerhalb von 30 Tagen nach Zustellung zu löschen. Sobald eine Bestellung abgeschlossen und älter als dieser Zeitraum ist, entfernt das Modul aus seiner eigenen Tabelle Name, E-Mail, Straße, Ort, Region, Postleitzahl und Telefonnummer des Käufers sowie die gespeicherten Amazon-Rohdaten. Bestellsummen, Steuern, Gebühren und Zielland bleiben erhalten, Ihre Auswertungen und Umsatzsteueraufzeichnungen sind also nicht betroffen.';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_c9274fdfe06e9b2c44c404eea92a96f1'] = 'Bestellung(en) warten auf die Löschung;';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_b534933c730ce57ed3ab62ce5c1c3150'] = 'bereits gelöscht.';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_5ee6f3e1aae989cfd5b4bd83d235e0f8'] = 'Jetzt löschen';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_6ada5ba7b164dbad1d1620f4f12963b6'] = 'Löschung der Käuferdaten';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_4ab9e6c00c5055c58feffff5ae55cd84'] = 'Ein (für die Amazon-Konformität erforderlich)';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_d15305d7a4e34e02489c74a5ef542f36'] = 'Aus';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_9a89fce15c653813bba97088f4242469'] = 'Diese Option abzuschalten bedeutet, Amazon-Käuferdaten länger aufzubewahren, als Amazon erlaubt. Tun Sie das nur, wenn eine gesetzliche Pflicht es verlangt und Sie diese belegen können.';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_114fc58e687755f400c4ff77e00b9cf7'] = 'Auch Kunde und Adresse in PrestaShop anonymisieren';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_06d16f3c4536d713eafb1f97f25657f4'] = 'Nein (empfohlen)';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_b3a631ecd8088b96eeab29ebb7670789'] = 'Bewusst standardmäßig deaktiviert. PrestaShop erzeugt Rechnungen aus der gespeicherten Adresse; sie zu anonymisieren verändert also Dokumente, die Sie gesetzlich unverändert aufbewahren müssen — und eine aufbewahrungspflichtige Rechnung ist genau die Ausnahme, die Amazons Richtlinie zulässt. Aktivieren Sie die Option erst nach eigener rechtlicher Beratung. Ist sie aktiv, wird ein Kunde nur anonymisiert, wenn alle seine Bestellungen Amazon-Bestellungen sind, die bereits gelöscht wurden; Ort, Postleitzahl und Land bleiben erhalten, damit die umsatzsteuerliche Behandlung nachvollziehbar bleibt.';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_4afb955a8ca5e46fdaf13febfabde9b0'] = 'Kundengruppe für Amazon-Käufer';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_650e8746625f41e4234739e9894cbb78'] = '-- Shop-Standard --';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_67b7390afec4abee3eaecd923f291c15'] = 'Externer Warenkorb (Bestand für unbezahlte Bestellungen reservieren)';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_f9f2d03af364aa656f60472f050f5ce9'] = 'Amazon zeigt einen laufenden Kaufvorgang als Bestellung im Status „Pending“. Mit dieser Option nimmt das Modul die betreffenden Einheiten sofort aus dem PrestaShop-Bestand, damit kein anderer Kanal sie verkaufen kann, und gibt sie zurück, falls die Bestellung nie zahlungspflichtig wird. Erfordert den Import von Pending-Bestellungen — das übernimmt das Modul automatisch, sobald die Option aktiv ist — sowie den Cron remote_cart zum Auflösen der Reservierungen.';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_606e569ed905da68a3f26de02575c6d9'] = 'Reservierung freigeben nach';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_4e9a4f12657cf4a16631d3bfbbd3ea93'] = 'Karenzzeit, bevor der Bestand einer weiterhin in Pending hängenden Bestellung zurückgegeben wird. 4 Stunden sind ein sicherer Standardwert — Amazon braucht mitunter eine Weile, um eine Bestellung auf Unshipped zu setzen.';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_a2d4829bd7afcb0622263a02a3b7a5fc'] = 'Bestellungen ohne ausreichenden Bestand';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_64f05d6bfbce6140c765c29e952478b7'] = 'PS-Bestellung trotzdem anlegen';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_9d7f6ecb0a0a1a38c076bc7a432c4907'] = 'Zur manuellen Prüfung unter Ausstehende Bestellungen parken';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_dacbbee8d1ca69a51619dc28dcd68e21'] = 'Ist die Option aktiv, warten vorbereitete Bestellungen, deren Produkte keinen Bestand haben (und nicht ohne Bestand bestellbar sind), auf der Registerkarte Ausstehende Bestellungen, statt zu PS-Bestellungen zu werden.';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_7a8156b022b1920dc000a4274b89a638'] = 'Standard-Versanddienstleister';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_9e98c820ff3d4cea82c3d4a4412c9471'] = '-- Keiner --';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_ac8d0bb27bf0dea8f2b54d14c28511e6'] = 'Standard-Bestellstatus';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_12dbd64f2bc9a6277ee7b95e9a2349dd'] = 'Zuordnung importierter Bestellungen';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_5cbc8ff529ecab618089ef063e3be9d2'] = 'Amazon nennt Ihnen die dem Käufer zugesagte Liefergeschwindigkeit. Ordnen Sie jede einem PrestaShop-Versanddienstleister zu, damit importierte Bestellungen die richtige Versandart tragen; nicht zugeordnete Geschwindigkeiten nutzen den obigen Standarddienstleister.';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_9fd1338f1dd68b2455075cc183be657f'] = 'Amazon-Liefergeschwindigkeit';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_15f87e0fa572c90443e2c0dc75d66819'] = '-- Standard-Versanddienstleister --';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_4fb6f1cf6de6ffac53ce3a98e1263f7a'] = 'Erweiterte Statusregeln';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_1eb7e0300a389884bba094f84a1dfce1'] = 'Geben Sie bestimmten Bestellarten einen eigenen PrestaShop-Status — etwa Prime-Bestellungen einen auffälligen Status, den Ihr Lager nicht übersehen kann, oder FBA-Bestellungen direkt „Versandt“. Die Regeln werden von oben nach unten geprüft, die erste Übereinstimmung gewinnt; „Beliebig“ ignoriert das jeweilige Merkmal. Eine Regel ohne Status wird übersprungen.';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_be7938e9a87618a98a7b6b47e12aa44b'] = 'Prime';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_84806d51f6ac4f75d8000b3cc6e56bb3'] = 'FBA';
