$_MODULE['<{amazonmarketplacepro}prestashop>configure_7c4615bb64b230fb813067a01d5dde92'] = 'Speichern Sie zuerst die Einstellungen. Es werden nur ungelesene Nachrichten abgerufen, und eine Nachricht gilt erst dann als gelesen, wenn sie sicher im Kundenservice liegt. Planen Sie den Cron fetch_messages für den automatischen Betrieb ein.';
