$_MODULE['<{amazonmarketplacepro}prestashop>configure_f582581b416fc00c920a086fa0994f55'] = 'Irgendetwas muss den Shop regelmäßig aufrufen, denn ein Shop führt nur dann Code aus, wenn eine Anfrage eintrifft. Wählen Sie, wer diesen Aufruf übernimmt.';
