$_MODULE['<{amazonmarketplacepro}prestashop>configure_f3604b94532854eabcb2fe73cad7f865'] = 'Fügen Sie diese eine Zeile in Ihr Hosting-Kontrollpanel oder Ihre Crontab ein. Zwischen Ihrem Shop und seinem Zeitplan steht dann nichts — deshalb die Empfehlung.';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_b1481f64dd0ca696a1845d6585cb098b'] = 'Jeder Aufruf führt nur das aus, was die Tabelle unten als fällig ausweist — ein Fünf-Minuten-Cron bedeutet also keine Synchronisierung alle fünf Minuten.';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_0cd2f5c5335a77f8d7c4522d414014dd'] = 'Für Hosting ohne Crontab. Unser Server ruft Ihren Shop alle fünf Minuten auf, damit Ihre Intervalle exakt eingehalten werden — Sie müssen nichts einrichten.';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_faa4a350ec0dc4e558f827d5cdf6c2db'] = 'Zwei Dinge sollten Sie vorher wissen. Die Adresse Ihres Shops und sein Cron-Token werden auf unserem Server gespeichert, denn dieses Token erlaubt dem Aufruf überhaupt erst, einen Lauf zu starten. Und wenn unser Server nicht erreichbar ist, pausiert Ihr Zeitplan, bis er wieder da ist.';
