$_MODULE['<{amazonmarketplacepro}prestashop>configure_3f4f37feac232d245ca3044c7707bdf5'] = 'Exportieren Sie alle Produkte und Kombinationen, korrigieren Sie Artikelnummern und Barcodes in einer Tabellenkalkulation und laden Sie die Datei wieder hoch. Geschrieben werden nur Artikelnummer, EAN, UPC und Lieferantenartikelnummer; die Schlüssel- und Namensspalten sind schreibgeschützt.';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_d334670c5c0ccd4279522bca993b7da2'] = 'Dieser Vorgang ändert Ihren PrestaShop-Katalog direkt und lässt sich nicht rückgängig machen — sichern Sie zuerst Ihre Datenbank. An Amazon wird nichts gesendet. Erledigen Sie das vor der Veröffentlichung, sonst entstehen doppelte SKUs bei Amazon.';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_c04f1e4841a6af78088d6ccf6f3a8a76'] = 'CSV exportieren';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_28ec2d08ef97978d3e7776c33a75592a'] = 'CSV importieren';
