$_MODULE['<{amazonmarketplacepro}prestashop>configure_3138e8a3564f298599dd32146104b63a'] = 'Angebote bei Amazon löschen';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_79f1b4c3c4edb48dd3bae5325b2ae846'] = 'Entfernt Angebote bei Amazon für Produkte, die Sie nicht mehr verkaufen — gelöscht, deaktiviert oder auf der Produktseite für Amazon abgeschaltet. Prüfen Sie die Liste zuerst: Das Löschen entfernt das Angebot samt seiner Historie bei Amazon und ist von hier aus nicht umkehrbar.';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_2d0e5660bea8a218a576ac7526dad77b'] = 'Wenn Sie den Verkauf nur vorübergehend einstellen möchten, hält die Veröffentlichung mit Menge 0 (Standardwerte für Angebote) das Angebot und seine Bewertungen am Leben.';
