$_MODULE['<{amazonmarketplacepro}prestashop>configure_82bc17e96acf57785719059127ef87a0'] = 'PS mit Amazon abgleichen';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_ad00d196cda52dc481df2a495dc5b8e2'] = 'Liest Ihren PrestaShop-Katalog und markiert je SKU, was von Amazon abweicht: Beschreibung, Aufzählungspunkte, Marke, Bilder, EAN und Kategorien. Der Vergleich erscheint unten.';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_4c1b4876ccaceb6a334a3d712076d859'] = 'ASINs über EAN zuordnen';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_46d9cde3daffdb463a8e3cca14a15d8e'] = 'Optional. Für Produkte, die Amazon bereits verkauft, findet es die vorhandene Produktseite über die EAN, sodass Sie ihr ein Angebot hinzufügen, statt eine doppelte Produktseite anzulegen.';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_76fe281cff4e7e7292b1c1a68add27b3'] = 'An Amazon senden';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_c60fbb93366c2db82e7f15b891519249'] = 'Sendet, was der Vergleich als ausstehend markiert. Bis zu 25 SKUs gehen einzeln und werden sofort beantwortet; mehr gehen als ein einzelner Feed, den Sie unter Feed-Status verfolgen.';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_3110cdebee6849c61252bfb7860c2700'] = 'Amazon → PrestaShop';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_123999c78f3b0fb3c2882359df62183a'] = 'Holen Sie Amazon-Angebote nach PrestaShop. Der erste Schritt liest und vergleicht nur; im zweiten wählen Sie nach Blick auf die Tabelle, was geschrieben wird.';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_7a39a1aacfcb9ac0960364ad6017a5ce'] = 'Amazon mit PS abgleichen';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_ac2360e03b18358b7be754f743139fed'] = 'Liest Ihre Amazon-Angebote und markiert je SKU, was PrestaShop fehlt oder anders enthält. Der Vergleich erscheint unten. In PrestaShop wird noch nichts geschrieben.';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_35ed5077b53753fe6892726329a04f98'] = 'Wählen Sie, was mit dem Vergleich geschehen soll. A legt an, was PrestaShop fehlt; B ändert, was bereits vorhanden ist.';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_02c8524ee3be6ffab84262c6c8dc44f1'] = 'Die Produkte anlegen, die PrestaShop nicht hat';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_4f865e01e018cbce51a247cef297f647'] = '-- In die Kategorie Startseite importieren --';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_0355d36f2c8a1eab81dcb57c9ccce785'] = 'PS-Produkte aus Angeboten anlegen, die es nur bei Amazon gibt';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_3827a19c1cab90f7baec0f76c4750697'] = 'Produkte, die bei Amazon vorhanden sind, in PrestaShop aber fehlen, werden als INAKTIVE Produkte (Titel, Beschreibung, Marke, Preis, Bestand, Bilder) in der gewählten Kategorie zur Prüfung angelegt. Die Preise werden ohne Steuerregel importiert — weisen Sie vor dem Aktivieren eine zu.';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_899f5890a5efebebccbc8d5fed9367b7'] = 'Die Produkte aktualisieren, die PrestaShop bereits hat';
