$_MODULE['<{amazonmarketplacepro}prestashop>configure_2bd6721be1d817ad2cfb2bac10f00cc7'] = 'Aufzählungspunkte als Merkmale';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_0caf70a852e40009c45fab32815b698e'] = 'Deaktivieren, was Amazon nicht mehr führt';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_0b56f593004334d4fe680149f0b5dc6e'] = 'Von Amazon aktualisieren';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_9be5c35a00a021a4768162f65558fc35'] = 'Bei Produkten, die in beiden Katalogen vorhanden sind, werden die angehakten Felder in PrestaShop mit den Werten von Amazon überschrieben. Jedes Feld ist unabhängig — haken Sie nur an, was überschrieben werden soll. Der Vorgang lässt sich nicht rückgängig machen, sichern Sie also vorher. Die Preise kommen als Bruttopreise an und werden über die Steuerregel des jeweiligen Produkts umgerechnet.';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_f09455b329365f7fdf49ea763abc10d0'] = 'Feed-Status';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_de64a1d2acd922dc141be655d48fa0c0'] = 'Eine Sendung mit mehr als 25 SKUs geht als ein einziges Feed-Dokument an Amazon, das Amazon im Hintergrund verarbeitet, statt sofort zu antworten. Prüfen Sie hier, ob sie abgeschlossen ist und was abgelehnt wurde. Kleinere Übertragungen werden direkt unter der Sende-Schaltfläche beantwortet.';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_05f782a70c60f04701a1edb4a0c448e8'] = 'Feed-Status prüfen';
